def handle(query, state):
    import shlex, re

    # Virtual filesystem lives in state
    vfs = state.get('files', {})
    cache = state.get('cache', {})

    def run_cmd(argv):
        """Simulate a tiny set of image/file commands against the virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]
        if cmd == 'curl':
            # -s (silent), -o (output file)
            output_file = None
            url = None
            i = 0
            while i < len(args):
                if args[i] == '-o' and i + 1 < len(args):
                    output_file = args[i + 1]
                    i += 2
                elif args[i] == '-s':
                    i += 1
                else:
                    url = args[i]
                    i += 1
            if url and url.startswith('file://'):
                path = url[7:]
                content = vfs.get(path)
                if content is None:
                    return f'curl: (37) Couldn\'t read a file:// URL\n'
                if output_file:
                    cache[output_file] = content
                    return ''
                return content
            return 'curl: unsupported protocol\n'
        elif cmd == 'convert':
            # convert input.jpg -resize 100x100 output.jpg
            # Minimal parsing: last arg is output, -resize X, rest is input
            if len(args) < 3:
                return 'convert: not enough args\n'
            output_file = args[-1]
            input_file = args[0]
            # Simulate: grab input from vfs or cache, put output in cache
            input_content = vfs.get(input_file) or cache.get(input_file)
            if input_content is None:
                return f'convert: unable to open image \'{input_file}\'\n'
            # Simulate thumbnail generation
            thumb_content = f'THUMB[{len(input_content)} bytes]'
            cache[output_file] = thumb_content
            return ''
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path) or cache.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'echo':
            return ' '.join(args) + '\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on ';' and run each segment in sequence, concatenating output.
        Does NOT support $() or backtick expansion."""
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    url = (query.get('url') or [''])[0]
    if not url:
        body = 'Usage: ?url=<image_url>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    # The vulnerable call: url is passed unsanitised into the shell emulator
    # Intended workflow: curl -s -o /tmp/orig.jpg <url> && convert /tmp/orig.jpg -resize 100x100 /tmp/thumb.jpg
    output = shell_exec(f'curl -s -o /tmp/orig.jpg {url} && convert /tmp/orig.jpg -resize 100x100 /tmp/thumb.jpg')
    if 'command not found' in output or 'No such file' in output:
        return 200, {'Content-Type': 'text/plain'}, output
    return 200, {'Content-Type': 'image/jpeg'}, cache.get('/tmp/thumb.jpg', b'GIF89a')
